PROTOCOL_PREFIX = "@@NINE_JSON@@"


def emit(payload: dict[str, Any]) -> None:
    print(
        PROTOCOL_PREFIX
        + json.dumps(json_safe(payload), ensure_ascii=False, allow_nan=False),
