        sample_root = self.run_root / f"repeat_{repetition}" / sample_name
        sample_root.mkdir(parents=True, exist_ok=True)
        analysis_input = (
            self._copy_input(image_path, sample_root)
            if self.stage_input
            else image_path
        )
        request_id = f"{sample_name}-{repetition}-{uuid.uuid4().hex[:8]}"
        started = time.perf_counter()
        responses: dict[str, Any] = {}
        with ThreadPoolExecutor(max_workers=3) as pool:
            futures = {
                pool.submit(
                    client.analyze,
                    request_id,
                    analysis_input,
                    sample_root,
                    self.request_timeout_seconds,
                ): name
                for name, client in self.clients.items()
            }
            for future in as_completed(futures):
                name = futures[future]
                try:
                    responses[name] = future.result()
                except Exception as exc:
                    responses[name] = {"service": name, "status": "failed", "message": f"{type(exc).__name__}: {exc}"}
        return self._write_indexes(
            sample_root,
            analysis_input,
            responses,
            time.perf_counter() - started,
        )

    def close(self) -> None:
        clients = list(self.clients.values())
        if clients:
            with ThreadPoolExecutor(max_workers=len(clients)) as pool:
                futures = [pool.submit(client.close) for client in clients]
                for future in futures:
                    try:
                        future.result()
                    except Exception:
                        # Continue reaping the remaining services. The caller
                        # is already in a recovery/shutdown path.
                        continue
        self.clients.clear()
